local a=require("fcs.io.cfgspec")local b=require("fcs.io.fsx")local c={}function c.bind(d,e,f)if d.thrusters[e]~=nil then d.thrusters[e]=f elseif d.sensors[e]~=nil then d.sensors[e]=f elseif e=="fuelRelay"then d.fuelRelay=f end;return d end;function c.measureWrite(g,h,i)local j=os.epoch("utc")for k=1,i do g:setThruster(h,k%2==0)end;return(os.epoch("utc")-j)/i end;local l="/eh2_hw_config.tbl"local m=b.read;local n=b.writeAtomic;local function o(read)local p,q=a.load("devbind",read)if not q then local r=read(l)if r~=nil then local s=textutils.unserialise(r)if type(s)=="table"then p=a.merge("devbind",a.splitLegacy(s).devbind)end end end;return p end;local function t(read)return a.load("senscal",read)end;local function u(v)for w,f in ipairs(v.getNames())do print(f.."  ["..tostring(v.getType(f)).."]")end end;function c.run()local v=require("fcs.io.shim")local x=require("fcs.io.backend")local d=o(m)while true do print("\n== EH2 PROBE == 1 discover 2 bind 3 sensors 4 thruster 5 timing 6 roles 7 methods q quit")local y=read()if y=="1"then u(v)elseif y=="2"then write("role (e.g. FL / gimbal / fuelRelay): ")local e=read()write("peripheral name: ")local f=read()d=c.bind(d,e,f)a.save("devbind",d,n)print("bound "..e.." -> "..f)elseif y=="3"then local z={thrusters=d.thrusters,sensors=d.sensors,fuelRelay=d.fuelRelay,bindings=t(m)}local A=x.new(v,z)A:sensors()for w=1,10 do local B=A:sensors()print(("alt %.2f v %.2f pitch %.3f roll %.3f hdg %.3f yawR %.3f sway %.2f surge %.2f gnd %s"):format(B.altitude,B.vSpeed,B.pitch,B.roll,B.heading,B.yawRate,B.swayVel,B.surgeVel,tostring(B.onGround)))sleep(0.3)end elseif y=="4"then write("peripheral NAME (e.g. thruster_1): ")local f=read()local C=f~=""and v.wrap(f)or nil;if not C then print("no such peripheral: "..tostring(f))elseif not C.setPower then print(tostring(f).." has no setPower. Its methods:")local D=peripheral.getMethods(f)if D then local B=""for w,E in ipairs(D)do B=B..E.." "end;print(B)else print("(none)")end else C.setPower(15)sleep(0.5)print("thrustKN="..tostring(C.getCurrentThrustKN and C.getCurrentThrustKN()or"n/a"))C.setPower(0)end elseif y=="5"then write("peripheral NAME: ")local f=read()local C=f~=""and v.wrap(f)or nil;if not C or not C.setPower then print("no thruster peripheral: "..tostring(f))else local i=40;local j=os.epoch("utc")for k=1,i do C.setPower(k%2==0 and 15 or 0)end;C.setPower(0)print(("avg %.2f ms/write over %d writes"):format((os.epoch("utc")-j)/i,i))end elseif y=="6"then print("THRUSTERS: FL FR RL RR (lift) | YFL YFR YRL YRR (lateral) | MAIN (accel) | FRL FRR (front brakes)")print("SENSORS: altimeter gimbal navTable downOptical velFront velRear velMedial | fuelRelay")elseif y=="7"then write("peripheral NAME: ")local f=read()local D=peripheral.getMethods(f)if not D then print("no such peripheral: "..tostring(f))else local B=""for w,E in ipairs(D)do B=B..E.." "end;print(B)end elseif y=="q"then return end end end;return c